    public function all(): array
    {
        return [
            $this->r('rundstykker-med-bakepulver', 'Rundstykker med bakepulver, uten heving', 'Brød og rundstykker', 'Seks små rundstykker som røres sammen og stekes med en gang.', '15 min', '35 min', '6 rundstykker', false, false, 'Bolle, stekebrett, bakepapir, målebeger', ['4 dl hvetemel','1 dl havregryn','2 ts bakepulver','1/2 ts salt','2 dl melk','2 ss olje'], ['Sett ovnen på 225 °C over- og undervarme. Legg bakepapir på brettet.','Bland det tørre. Rør inn melk og olje til en litt klissete deig.','Form seks rundstykker med våte hender. Stek midt i ovnen i 18–20 minutter.'], ['Bruk grovt mel for inntil halvparten av hvetemelet, men tilsett 1–2 ss ekstra melk ved behov.','Avkjøl på rist så skorpen holder seg sprø.'], ['Gluten (hvete, havre)','Melk']),
            $this->r('scones', 'Scones', 'Brød og rundstykker', 'Fire grove scones med havregryn og uten gjær.', '10 min', '28 min', '4 scones', false, false, 'Bolle, stekebrett, bakepapir', ['2 dl hvetemel','1 dl havregryn','2 ts bakepulver','1/2 ts salt','2 dl melk','2 ss olje'], ['Sett ovnen på 225 °C over- og undervarme.','Bland alt det tørre. Rør inn melk og olje raskt.','Sett fire topper på brettet med en skje. Stek midt i ovnen i 15–18 minutter.'], ['Ikke rør mer enn nødvendig; da blir sconesene luftigere.','Rosiner eller 1 dl revet ost kan tilsettes. Allergeninnholdet kan da endres.'], ['Gluten (hvete, havre)','Melk']),
            $this->r('pannebrod-uten-gjaer', 'Pannebrød uten gjær', 'Brød og rundstykker', 'Flate brød som stekes raskt i tørr panne.', '15 min', '25 min', '4 små brød', true, true, 'Bolle, stekepanne, kjevle eller flaske', ['3 dl hvetemel','1 ts bakepulver','1/2 ts salt','1 1/2 dl vann','1 ss olje'], ['Bland mel, bakepulver og salt. Rør inn vann og olje og kna kort til en smidig deig.','Del i fire og kjevle eller trykk ut tynne leiver.','Stek i tørr, varm panne 2–3 minutter per side, til brødene har flekker og er gjennomstekte.'], ['Legg ferdige brød i et rent kjøkkenhåndkle så de holder seg myke.','Bytt ut 1 dl hvetemel med grovt mel og ha i litt ekstra vann.'], ['Gluten (hvete)']),
            $this->r('enkelt-brod-med-bakepulver', 'Enkelt brød med bakepulver', 'Brød og rundstykker', 'Et lite formbrød uten ventetid.', '15 min', '55 min', '1 lite brød (ca. 1 liter form)', false, false, 'Bolle, liten brødform, bakepapir', ['4 dl hvetemel','2 dl grovt mel','3 ts bakepulver','1 ts salt','3 dl melk','2 ss olje'], ['Sett ovnen på 200 °C over- og undervarme. Kle formen med bakepapir.','Bland det tørre. Rør inn melk og olje til en tykk røre.','Ha røren i formen. Stek nederst i ovnen i 38–42 minutter. Avkjøl på rist.'], ['Brødet er ferdig når det høres hult ut under og ikke er vått i midten.','Skjær i skiver og frys ned det som ikke brukes raskt.'], ['Gluten (hvete)','Melk']),
            $this->r('grove-matmuffins-med-ost', 'Grove matmuffins med ost', 'Brød og rundstykker', 'Små, saftige muffins som passer som et enkelt måltid.', '15 min', '35 min', '6 muffins', false, false, 'Bolle, muffinsform eller seks papirformer, stekebrett', ['2 dl hvetemel','1 dl grovt mel','2 ts bakepulver','1/2 ts salt','2 egg','1 1/2 dl melk','2 ss olje','1 dl revet ost','1 dl småkuttede grønnsaker'], ['Sett ovnen på 200 °C over- og undervarme.','Bland mel, bakepulver og salt. Visp egg, melk og olje lett sammen.','Rør væsken inn i det tørre. Vend inn ost og grønnsaker.','Fordel i seks former. Stek midt i ovnen i 18–22 minutter.'], ['Bruk frosne grønnsaker som er tint og godt avrent.','Skinke kan tilsettes; da kan allergeninnholdet endres.'], ['Gluten (hvete)','Egg','Melk']),
            $this->r('sjokoladekake-i-liten-form', 'Sjokoladekake i liten form', 'Enkel bakst og kaker', 'En liten, saftig sjokoladekake til en 20 cm form.', '15 min', '45 min', '1 liten kake (ca. 20 cm form)', false, false, 'Bolle, 20 cm rund form eller liten ildfast form, visp', ['2 egg','1 1/2 dl sukker','1 dl melk','75 g smør eller margarin','2 dl hvetemel','1/2 dl kakaopulver','1 ts bakepulver','1/2 ts vaniljesukker'], ['Sett ovnen på 175 °C over- og undervarme. Smør formen eller bruk bakepapir.','Smelt smør og la det avkjøle litt. Visp egg og sukker lett sammen.','Rør inn melk og smør. Bland det tørre og rør det inn til en jevn røre.','Stek midt i ovnen i 25–30 minutter. La kaken avkjøle før den deles.'], ['Margarinen kan erstatte smør. Da kan allergeninnholdet endres.','Kaken skal være fast i kanten og gjerne litt fuktig i midten.'], ['Egg','Gluten (hvete)','Melk']),
            $this->r('enkel-eplekake', 'Enkel eplekake', 'Enkel bakst og kaker', 'Liten eplekake med kanel og vanlige basisvarer.', '15 min', '55 min', '1 liten kake (ca. 20 cm form)', false, false, 'Bolle, 20 cm rund form eller liten ildfast form, visp', ['75 g smør eller margarin','1 dl sukker','1 egg','2 dl hvetemel','1 ts bakepulver','1/2 dl melk','2 små epler','1 ts kanel','1 ss sukker'], ['Sett ovnen på 175 °C over- og undervarme. Smør formen.','Rør smør og sukker sammen. Rør inn egget, deretter mel, bakepulver og melk.','Ha røren i formen. Skjær eplene i tynne båter og trykk dem lett ned. Strø over kanel og sukker.','Stek midt i ovnen i 35–40 minutter.'], ['Pære eller faste plommer kan brukes i stedet for eple.','Skyll frukten før den kuttes.'], ['Egg','Gluten (hvete)','Melk']),
            $this->r('havrekjeks', 'Havrekjeks', 'Enkel bakst og kaker', 'Små, sprø kjeks med havre og lite utstyr.', '15 min', '30 min', '12 små kjeks', false, false, 'Bolle, stekebrett, bakepapir, gaffel', ['75 g smør eller margarin','1 dl sukker','1 dl hvetemel','2 dl havregryn','1/2 ts bakepulver','1 ss melk'], ['Sett ovnen på 175 °C over- og undervarme. Smelt smøret.','Bland alle ingrediensene til en deig.','Trill 12 små kuler, legg dem på brettet og trykk flate med en gaffel.','Stek midt i ovnen i 10–12 minutter. La kjeksene bli kalde på brettet.'], ['En klype kanel passer godt.','Bruk glutenfrie havregryn og glutenfritt mel ved behov; allergeninnholdet endres.'], ['Gluten (hvete, havre)','Melk']),
            $this->r('bananmuffins', 'Bananmuffins', 'Enkel bakst og kaker', 'Seks små muffins som bruker modne bananer.', '15 min', '35 min', '6 muffins', false, false, 'Bolle, gaffel, muffinsform eller papirformer', ['2 modne bananer','1 egg','1/2 dl sukker','50 g smør eller margarin','2 dl hvetemel','1 ts bakepulver','1/2 ts kanel'], ['Sett ovnen på 180 °C over- og undervarme.','Mos bananene med en gaffel. Smelt smøret.','Rør sammen banan, egg, sukker og smør. Vend inn mel, bakepulver og kanel.','Fordel i seks former. Stek midt i ovnen i 18–22 minutter.'], ['Jo modnere bananer, desto søtere blir muffinsene.','Avkjøl før oppbevaring i en tett boks.'], ['Egg','Gluten (hvete)','Melk']),
            $this->r('smuldrepai-med-frukt-eller-baer', 'Smuldrepai med frukt eller bær', 'Enkel bakst og kaker', 'Liten pai med frukt eller bær og sprø smuler på toppen.', '15 min', '45 min', '1 liten form (ca. 20 cm)', false, false, 'Liten ildfast form, bolle', ['300 g frukt eller bær','1 ss sukker','1 dl hvetemel','1 dl havregryn','1/2 dl sukker','75 g kaldt smør eller margarin','1/2 ts kanel'], ['Sett ovnen på 200 °C over- og undervarme.','Skyll og kutt frukten ved behov. Legg den i formen med 1 ss sukker.','Bland mel, havregryn, sukker og kanel. Smuldre inn kaldt smør med fingrene.','Fordel smulene over frukten. Stek midt i ovnen i 25–30 minutter.'], ['Frosne bær kan brukes direkte fra fryseren; stek 5 minutter ekstra ved behov.','Skyll frisk frukt og bær før bruk.'], ['Gluten (hvete, havre)','Melk']),
        ];
    }

    public function find(string $slug): ?array
    {
        foreach ($this->all() as $recipe) if ($recipe['slug'] === $slug) return $recipe;
        return null;
    }

    private function r(string $slug, string $title, string $category, string $description, string $work, string $total, string $yield, bool $quick, bool $onePan, string $equipment, array $ingredients, array $steps, array $tips, array $allergens): array
    {
        return compact('slug', 'title', 'category', 'description', 'work', 'total', 'yield', 'equipment', 'ingredients', 'steps', 'tips', 'allergens');
    }
}
